BASE = "https://api.thepulseapi.com/api/v1"

class Pulse:
 """Thin wrapper over the HTTP API. Every call is POST and returns JSON."""

 def init (self, api key: str, organization id: str, timeout: float = 5.0):
 self. org = organization id
 self. client = httpx.Client(
 base url=BASE,
 timeout=timeout,
 headers={"x-api-key": api key, "Content-Type": "application/json"},
 )

 def post(self, path: str, body: dict) - dict:
 # organizationId is required on nearly every endpoint and is read from the body,
 # not from the key, so it is filled in here rather than at every call site.
 response = self. client.post(path, json={"organizationId": self. org, body})
 response.raise for status()
 return response.json()

 def track(self, session id: str, signals: list[dict]) - dict:
 return self. post("/track", {"sessionId": session id, "signals": signals})

 def session(self, session id: str) - dict:
 # /session takes only sessionId. Sending organizationId is harmless.
 return self. post("/session", {"sessionId": session id})

def ranked catalog(self, session id: str, limit: int = 24, kwargs) - dict:
 return self. post(
 "/catalog/ranked", {"sessionId": session id, "limit": limit, kwargs}
 )

