use serde::{Deserialize, Serialize};
use serde json::{json, Value};
use std::time::Duration;

const BASE: &str = "https://api.thepulseapi.com/api/v1";

#[derive(Serialize)]
pub struct Signal {
 #[serde(rename = "type")]
 pub kind: String,
 pub value: String,
}

#[derive(Clone)]
pub struct Pulse {
 // reqwest::Client is already an Arc around a connection pool, so cloning it is cheap
 // and sharing one across tasks is the intended use. Building one per request is not.
 http: reqwest::Client,
 org id: String,
}

impl Pulse {
 pub fn new(api key: &str, org id: impl Into ) - reqwest::Result {
 let mut headers = reqwest::header::HeaderMap::new();
 let mut key = reqwest::header::HeaderValue::from str(api key).expect("valid api key");
 key.set sensitive(true);
 headers.insert("x-api-key", key);

Ok(Self {
 http: reqwest::Client::builder()
 .default headers(headers)
 .timeout(Duration::from secs(5))
 .build()?,
 org id: org id.into(),
 })
 }

 async fn post(&self, path: &str, mut body: Value) - reqwest::Result {
 // organizationId is required on nearly every endpoint and comes from the body,
 // not from the key.
 body["organizationId"] = json!(self.org id);

 self.http
 .post(format!("{BASE}{path}"))
 .json(&body)
 .send()
 .await?
 .error for status()?
 .json()
 .await
 }

 pub async fn track(&self, session id: &str, signals: Vec ) - reqwest::Result {
 self.post("/track", json!({ "sessionId": session id, "signals": signals })).await
 }

 pub async fn ranked catalog(&self, session id: &str, limit: u32) - reqwest::Result {
 self.post("/catalog/ranked", json!({ "sessionId": session id, "limit": limit })).await
 }
}


