function pulse signals for current page(): array
{
 if (!function exists('is product')) {
 return []; // WooCommerce is not active; nothing here applies
 }

 if (is product()) {
 $product = wc get product(get the ID());
 if (!$product) {
 return [];
 }

 $terms = get the terms($product- get id(), 'product cat');
 $signals = [['type' = 'product view', 'value' = (string) $product- get id()]];

 if (is array($terms) && $terms) {
 $signals[] = ['type' = 'category view', 'value' = $terms[0]- slug];
 }

 return $signals;
 }

 if (is product category()) {
 $term = get queried object();
 return [['type' = 'category view', 'value' = $term- slug]];
 }

 if (is search()) {
 return [['type' = 'search', 'value' = get search query()]];
 }

 return [];
}


